/** @file Governed scheduler-facing consumer for the durable WhatsApp packet AI outbox. */
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import {
  createClient,
  type SupabaseClient,
} from "npm:@supabase/supabase-js@2.95.0";
import {
  processWorkerRequest,
  WorkerRequestError,
} from "../whatsapp-packet-ai-worker/index.ts";

const JSON_HEADERS = {
  "Content-Type": "application/json",
  "Cache-Control": "no-store",
  "Pragma": "no-cache",
  "X-Content-Type-Options": "nosniff",
};
const DEFAULT_MAX_JOBS = 3;
const MAX_JOBS_PER_TICK = 5;

type AdminClient = SupabaseClient;

type ConsumerAuthority =
  | { ok: true }
  | { ok: false; status: 401 | 403 | 500; error: string };

const respond = (body: Record<string, unknown>, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: JSON_HEADERS });

export function boundedMaxJobs(value: unknown): number {
  if (typeof value !== "number" || !Number.isInteger(value)) {
    return DEFAULT_MAX_JOBS;
  }
  return Math.min(MAX_JOBS_PER_TICK, Math.max(1, value));
}

async function requireConsumerAuthority(
  req: Request,
  admin: AdminClient,
): Promise<ConsumerAuthority> {
  const candidate = req.headers.get("x-oasis-worker-secret")?.trim() ?? "";
  if (!candidate) return { ok: false, status: 401, error: "unauthorized" };

  const { data, error } = await admin.rpc(
    "verify_whatsapp_packet_ai_consumer_secret",
    { _candidate: candidate },
  );
  if (error) {
    console.error(
      "[whatsapp-packet-ai-consumer] authority lookup failed",
      error.message.slice(0, 160),
    );
    return { ok: false, status: 500, error: "authority_unavailable" };
  }
  return data === true
    ? { ok: true }
    : { ok: false, status: 403, error: "forbidden" };
}

export async function consumeAvailableJobs(
  admin: AdminClient,
  maxJobs: number,
): Promise<Record<string, unknown>> {
  let processed = 0;
  let failed = 0;
  const errors: string[] = [];

  for (let index = 0; index < maxJobs; index += 1) {
    try {
      const result = await processWorkerRequest(admin, { claim_next: true });
      if (result.idle === true) {
        return {
          success: failed === 0,
          idle: processed === 0 && failed === 0,
          processed,
          failed,
          errors,
        };
      }
      processed += 1;
    } catch (error) {
      const message = error instanceof WorkerRequestError
        ? String(error.body.error ?? error.message)
        : error instanceof Error
        ? error.message
        : "PACKET_AI_FAILED";
      const code = message.split(":")[0].slice(0, 120);
      failed += 1;
      errors.push(code);

      if (
        code === "WORKER_NOT_CONFIGURED" ||
        code === "KNOWLEDGE_SNAPSHOT_NOT_ACTIVELY_GOVERNED" ||
        code.startsWith("KNOWLEDGE_SNAPSHOT_LOAD_FAILED")
      ) {
        break;
      }
    }
  }

  return {
    success: failed === 0,
    idle: false,
    processed,
    failed,
    errors,
  };
}

async function handleRequest(req: Request): Promise<Response> {
  if (req.method !== "POST") {
    return respond({ success: false, error: "METHOD_NOT_ALLOWED" }, 405);
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
  if (!supabaseUrl || !serviceRoleKey) {
    return respond({ success: false, error: "CONSUMER_NOT_CONFIGURED" }, 503);
  }

  const admin = createClient(supabaseUrl, serviceRoleKey, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
  const authority = await requireConsumerAuthority(req, admin);
  if (!authority.ok) {
    return respond(
      { success: false, error: authority.error },
      authority.status,
    );
  }

  const body = await req.json().catch(() => ({})) as Record<string, unknown>;
  const maxJobs = boundedMaxJobs(body.max_jobs);
  const result = await consumeAvailableJobs(admin, maxJobs);
  return respond(result, result.success === true ? 200 : 502);
}

if (import.meta.main) {
  serve(async (req) => {
    try {
      return await handleRequest(req);
    } catch (error) {
      const code = error instanceof Error ? error.message : "CONSUMER_FAILED";
      console.error("[whatsapp-packet-ai-consumer]", code.slice(0, 240));
      return respond({ success: false, error: code.slice(0, 240) }, 502);
    }
  });
}

/** @file Trusted WhatsApp packet AI worker with governed B2B case orchestration. */
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import {
  createClient,
  type SupabaseClient,
} from "npm:@supabase/supabase-js@2.95.0";
import {
  downloadGovernedWhatsAppMedia,
  parseGovernedWhatsAppMediaUrl,
  readBoundedResponseBody,
} from "../_shared/whatsappGovernedMediaFetch.ts";
import { sanitizeInterpretResult } from "../whatsapp-content-interpret/sanitize.ts";
import {
  buildGeminiRequest,
  callGeminiGenerateContent,
  GEMINI_MODEL,
  GEMINI_TIMEOUT_MS,
  type GeminiPart,
  type GeminiRequest,
  inlineMediaPart,
  textPart,
} from "../_shared/geminiProvider.ts";

export {
  parseGovernedWhatsAppMediaUrl as allowedMediaUrl,
  readBoundedResponseBody as readBoundedBody,
};

const JSON_HEADERS = { "Content-Type": "application/json" };
// Packets up to LEGACY_PACKET_MESSAGES keep the original best-effort media semantics. Larger packets (up to
// MAX_PACKET_MESSAGES) are interpreted only when every media item was retrieved, so none is silently omitted.
const LEGACY_PACKET_MESSAGES = 16;
const MAX_PACKET_MESSAGES = 32;
// The dispatch lease is 120 s and one Gemini call can take up to 90 s, so the sequential media phase is capped at
// 25 s (each fetch is also capped at the time remaining) to keep a packet inside its lease.
const MEDIA_PHASE_BUDGET_MS = 25_000;
const MAX_IMAGE_BYTES = 8 * 1024 * 1024;
const MAX_MEDIA_BYTES = 15 * 1024 * 1024;
const MAX_PACKET_MEDIA_BYTES = 24 * 1024 * 1024;
const MODEL = GEMINI_MODEL;
const PROVIDER = "google-gemini";
const INTERPRETATION_SCHEMA_VERSION = "wa-packet-interpretation/v1";
const PROMPT_POLICY_VERSION = "wa-packet-policy/v3";
const RESOLVER_POLICY_VERSION = "wa-resolver-policy/v1";
const MEDIA_TYPES = new Set(["image", "audio", "video", "document"]);
const ALLOWED_INTENTS = new Set([
  "NEW_ORDER",
  "AMENDMENT",
  "CANCELLATION",
  "ENQUIRY",
  "COMPLAINT",
  "PAYMENT_ADVICE",
  "ACCOUNT_QUERY",
  "DELIVERY_QUERY",
  "SPECIFICATION_QUERY",
  "OTHER",
  "UNCLEAR",
]);
const ALLOWED_DEPARTMENTS = new Set([
  "SALES",
  "FINANCE",
  "QUALITY",
  "DISPATCH",
  "LOGISTICS",
  "PRODUCTION",
  "PACKAGING",
  "OPERATIONS",
  "CUSTOMER_SERVICE",
]);
const ALLOWED_REPLY_CLEARANCE = new Set([
  "EMPLOYEE_REVIEW_REQUIRED",
  "SUBJECT_EXPERT_REVIEW_REQUIRED",
  "MANAGEMENT_APPROVAL_REQUIRED",
  "BLOCKED_INACCURATE_OR_UNSUPPORTED",
  "CLARIFICATION_REQUIRED",
  "SAFE_TO_SEND_AUTOMATICALLY",
]);
const DEFAULT_REPLY_CLEARANCE = "EMPLOYEE_REVIEW_REQUIRED";

const IMAGE_MIME = new Set([
  "image/jpeg",
  "image/png",
  "image/webp",
  "image/gif",
]);
const AUDIO_MIME = new Set([
  "audio/mpeg",
  "audio/mp3",
  "audio/mp4",
  "audio/x-m4a",
  "audio/ogg",
  "audio/wav",
  "audio/x-wav",
  "audio/webm",
]);
const VIDEO_MIME = new Set(["video/mp4", "video/webm", "video/quicktime"]);
const DOCUMENT_MIME = new Set(["application/pdf"]);
const MIME_ALLOWLIST_BY_TYPE = new Map<string, Set<string>>([
  ["image", IMAGE_MIME],
  ["audio", AUDIO_MIME],
  ["video", VIDEO_MIME],
  ["document", DOCUMENT_MIME],
]);

type PacketMessage = {
  provider_message_id: string | null;
  content: string | null;
  message_type: string | null;
  media_url: string | null;
  message_timestamp: string | null;
  packet_sequence: number | null;
};

export type LoadedMessage = {
  providerMessageId: string;
  content: string;
  messageType: string;
  mediaUrl: string;
  timestamp: string;
};

type DispatchLease = {
  id: string;
  packet_id: string;
  packet_revision: number;
  lease_token: string;
  execution_kind: "PACKET" | "CASE_CONTEXT";
  case_id: string | null;
  context_revision: number | null;
};

const respond = (body: Record<string, unknown>, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: JSON_HEADERS });

/** Typed worker execution failure for in-process and HTTP callers. */
export class WorkerRequestError extends Error {
  status: number;
  body: Record<string, unknown>;

  constructor(body: Record<string, unknown>, status: number) {
    super(
      typeof body.error === "string" ? body.error : "WORKER_REQUEST_FAILED",
    );
    this.status = status;
    this.body = body;
  }
}

const safeString = (value: unknown, max: number): string =>
  typeof value === "string" ? value.trim().slice(0, max) : "";

const safeStringArray = (
  value: unknown,
  maxItems: number,
  maxLength: number,
): string[] => {
  if (!Array.isArray(value)) return [];
  return value
    .filter((entry): entry is string => typeof entry === "string")
    .map((entry) => entry.trim().slice(0, maxLength))
    .filter(Boolean)
    .slice(0, maxItems);
};

const systemPrompt =
  `You are the B2B WhatsApp evidence interpreter and decision-support engine for Oasis Baklawa.
Understand the ENTIRE chronological evidence packet before a human decides. Evidence can be clean or badly typed English, Hindi/Devanagari, Roman Hinglish, phonetic spellings, abbreviations, misspellings, photographs, screenshots, handwriting, voice notes, videos, and PDF purchase orders.

Rules:
1. Preserve provenance. Cite provider_message_id for explicit facts and corrections.
2. Understand obvious spelling/transliteration variants, but never invent product, SKU, quantity, unit, price, customer, payment, stock, credit, delivery date, availability or promises.
3. Later explicit corrections supersede earlier conflicting instructions and must be recorded, not silently erased.
4. Read only visible/audible/documented facts. Illegible or unavailable evidence becomes an ambiguity.
5. Distinguish explicit facts from interpreted normalization.
6. Reach a concise B2B conclusion and recommended next HUMAN action. AI creates no commitment.
7. normalized_text must remain useful to downstream catalogue/quantity resolution and contain explicit quantities/corrections only.
8. Classify the business case, not merely whether it resembles an order. Use the narrowest supported intent.
9. Recommend one accountable response department and any contributor departments. This is advisory: never claim a person accepted ownership.
10. Draft a concise customer reply only from supported evidence. Never claim payment verified, stock available, credit approved, production complete, dispatch committed, or a delivery promise unless explicit authoritative evidence is in this packet. Automatic customer sends are decided only by deterministic Core policy after materialization, never by AI reply_clearance alone.
11. reply_clearance and draft_reply are advisory only. They do not grant automatic send authority. Core decides AUTO_SAFE_ACK, AUTO_CLARIFICATION, or HUMAN_OR_DEPARTMENT_REVIEW_REQUIRED from governed outcomes.
12. For mixed-intent packets, choose the primary intent and list contributor departments needed for one consolidated customer response.

Allowed primary/contributor department labels:
SALES, FINANCE, QUALITY, DISPATCH, LOGISTICS, PRODUCTION, PACKAGING, OPERATIONS, CUSTOMER_SERVICE.

Return JSON only:
{
  "normalized_text":"...",
  "extracted_text":"...",
  "language":"...",
  "confidence":0.0,
  "warnings":[],
  "source_kind":"packet",
  "conclusion":{
    "intent":"NEW_ORDER|AMENDMENT|CANCELLATION|ENQUIRY|COMPLAINT|PAYMENT_ADVICE|ACCOUNT_QUERY|DELIVERY_QUERY|SPECIFICATION_QUERY|OTHER|UNCLEAR",
    "summary":"...",
    "explicit_facts":[{"provider_message_id":"...","kind":"...","value":"..."}],
    "order_lines":[{"product_name":"...","sku":"","quantity":null,"unit":"","status":"explicit|interpreted|unclear","evidence_ids":["..."]}],
    "corrections":[{"provider_message_id":"...","supersedes":"...","replacement":"..."}],
    "ambiguities":[],
    "primary_department":"SALES|FINANCE|QUALITY|DISPATCH|LOGISTICS|PRODUCTION|PACKAGING|OPERATIONS|CUSTOMER_SERVICE|",
    "contributor_departments":[],
    "reply_clearance":"EMPLOYEE_REVIEW_REQUIRED|SUBJECT_EXPERT_REVIEW_REQUIRED|MANAGEMENT_APPROVAL_REQUIRED|BLOCKED_INACCURATE_OR_UNSUPPORTED|CLARIFICATION_REQUIRED|SAFE_TO_SEND_AUTOMATICALLY",
    "draft_reply":"...",
    "recommended_action":"...",
    "human_review_required":true,
    "automatic_action_authority":"HUMAN_OR_DEPARTMENT_REVIEW_REQUIRED"
  }
}`;

// skipcq: JS-R1005
export const validateMime = (type: string, mime: string): void => {
  const allowed = MIME_ALLOWLIST_BY_TYPE.get(type);
  if (!allowed) return;
  if (!allowed.has(mime)) {
    throw new Error(`UNSUPPORTED_${type.toUpperCase()}_TYPE`);
  }
};

function maxBytes(type: string): number {
  return type === "image" ? MAX_IMAGE_BYTES : MAX_MEDIA_BYTES;
}

export const handleAsync = <T>(
  maybePromise: PromiseLike<T>,
): Promise<[T, undefined] | [undefined, Error]> =>
  Promise.resolve(maybePromise)
    .then((data): [T, undefined] => [data, undefined])
    .catch((error): [undefined, Error] => [
      undefined,
      error instanceof Error ? error : new Error("ASYNC_TRANSPORT_FAILED"),
    ]);

type PostgrestRpcResponse<T> = {
  data: T;
  error: { message: string } | null;
};

function withDispatchLeaseRpcArgs(
  base: Record<string, unknown>,
  lease?: DispatchLease | null,
): Record<string, unknown> {
  if (!lease) return base;
  return {
    ...base,
    p_job_id: lease.id,
    p_lease_token: lease.lease_token,
    p_packet_revision: lease.packet_revision,
  };
}

async function rpcWithTransport<T>(
  failureCode: string,
  maybePromise: PromiseLike<PostgrestRpcResponse<T>>,
): Promise<T> {
  try {
    const [response, transportErr] = await handleAsync(maybePromise);
    if (transportErr) {
      throw new Error(
        `${failureCode}:${safeString(transportErr.message, 120)}`,
      );
    }
    if (response.error) {
      throw new Error(
        `${failureCode}:${safeString(response.error.message, 120)}`,
      );
    }
    return response.data;
  } catch (error) {
    throw error instanceof Error
      ? error
      : new Error(`${failureCode}:ASYNC_TRANSPORT_FAILED`);
  }
}

export type KnowledgeSnapshot = {
  id: string;
  schema_version: string;
  content_checksum: string;
  knowledge: Record<string, unknown>;
};

const MAX_KNOWLEDGE_CONTEXT_CHARS = 12000;

export function formatKnowledgeSnapshotContext(
  snapshot: KnowledgeSnapshot,
): string {
  const knowledgeJson = JSON.stringify(snapshot.knowledge);
  if (knowledgeJson.length > MAX_KNOWLEDGE_CONTEXT_CHARS) {
    throw new Error("KNOWLEDGE_SNAPSHOT_CONTEXT_TOO_LARGE");
  }
  return [
    "Governed intelligence knowledge snapshot",
    `schema_version=${snapshot.schema_version}`,
    `content_checksum=${snapshot.content_checksum}`,
    `knowledge=${knowledgeJson}`,
  ].join("\n");
}

function evidenceLabel(message: LoadedMessage, extra = ""): string {
  return `[evidence provider_message_id=${message.providerMessageId} type=${message.messageType}${
    message.timestamp ? ` time=${message.timestamp}` : ""
  }${extra}]`;
}

/** Rejects a packet whose message count exceeds the supported ceiling (deterministic, never retried usefully). */
export function assertPacketMessageCount(count: number): void {
  if (count > MAX_PACKET_MESSAGES) {
    throw new Error("INTERPRETATION_PACKET_TOO_LARGE");
  }
}

/**
 * For packets above the legacy size, every media item must have been retrieved and attached to the model
 * request. Otherwise the interpretation would claim coverage of evidence it never saw.
 */
export function assertOversizedMediaComplete(
  messages: LoadedMessage[],
  processedMediaIds: string[],
  failureCodes: string[] = [],
): void {
  if (messages.length <= LEGACY_PACKET_MESSAGES) return;
  // Count occurrences, not just ids: two messages may share a provider id (uniqueness is per provider),
  // and one successful fetch must not vouch for a failed sibling.
  const processedCounts = new Map<string, number>();
  for (const providerMessageId of processedMediaIds) {
    processedCounts.set(
      providerMessageId,
      (processedCounts.get(providerMessageId) ?? 0) + 1,
    );
  }
  const media = messages.filter((message) =>
    MEDIA_TYPES.has(message.messageType)
  );
  const missing = media.filter((message) => {
    const remaining = processedCounts.get(message.providerMessageId) ?? 0;
    if (remaining === 0) return true;
    processedCounts.set(message.providerMessageId, remaining - 1);
    return false;
  });
  if (missing.length > 0) {
    const reasons = [...new Set(failureCodes)].slice(0, 3).join(",");
    throw new Error(
      `OVERSIZED_PACKET_MEDIA_INCOMPLETE:missing=${missing.length}/${media.length}${
        reasons ? ` reasons=${reasons}` : ""
      }`,
    );
  }
}

/**
 * Rows without a provider message id are dropped after loading, which would silently remove evidence from
 * a large packet before the completeness check can see it. Reject them while the raw rows are still counted.
 */
export function assertProviderIdsPresent(
  rows: Array<{ provider_message_id?: string | null }>,
): void {
  if (rows.length <= LEGACY_PACKET_MESSAGES) return;
  if (rows.some((row) => !safeString(row.provider_message_id, 240))) {
    throw new Error("PACKET_MESSAGE_ID_MISSING");
  }
}

export type PrepareContentDeps = {
  download: typeof downloadGovernedWhatsAppMedia;
  now: () => number;
};

export async function prepareContent(
  messages: LoadedMessage[],
  knowledgeSnapshot: KnowledgeSnapshot,
  deps: PrepareContentDeps = {
    download: downloadGovernedWhatsAppMedia,
    now: Date.now,
  },
): Promise<{
  parts: GeminiPart[];
  warnings: string[];
  processedMediaIds: string[];
}> {
  const knowledgeContext = formatKnowledgeSnapshotContext(knowledgeSnapshot);
  const parts: GeminiPart[] = [
    textPart(`${systemPrompt}\n\n${knowledgeContext}`),
  ];
  const warnings: string[] = [];
  const processedMediaIds: string[] = [];
  const failureCodes: string[] = [];
  let packetBytes = 0;
  const mediaPhaseStartedAt = deps.now();

  for (const message of messages) {
    if (!MEDIA_TYPES.has(message.messageType)) {
      parts.push(
        textPart(
          `${evidenceLabel(message)}\n${message.content || "[empty text]"}`,
        ),
      );
      continue;
    }

    if (!message.mediaUrl) {
      failureCodes.push("MEDIA_URL_MISSING");
      warnings.push(
        `${message.providerMessageId}: ${message.messageType} has no retrievable media URL`,
      );
      parts.push(
        textPart(
          `${evidenceLabel(message, " media_unavailable=true")}\n${
            message.content || "[media unavailable]"
          }`,
        ),
      );
      continue;
    }

    try {
      const remainingMs = MEDIA_PHASE_BUDGET_MS -
        (deps.now() - mediaPhaseStartedAt);
      if (remainingMs <= 0) throw new Error("MEDIA_PHASE_BUDGET_EXCEEDED");
      const media = await deps.download(
        message.mediaUrl,
        maxBytes(message.messageType),
        remainingMs,
      );
      validateMime(message.messageType, media.mime);
      packetBytes += media.bytes.byteLength;
      if (packetBytes > MAX_PACKET_MEDIA_BYTES) {
        throw new Error("PACKET_MEDIA_TOO_LARGE");
      }

      parts.push(
        textPart(
          `${evidenceLabel(message)}${
            message.content ? `\nCAPTION: ${message.content}` : ""
          }`,
        ),
      );
      parts.push(inlineMediaPart(media.bytes, media.mime));
      processedMediaIds.push(message.providerMessageId);
    } catch (error) {
      const code = error instanceof Error
        ? error.message
        : "MEDIA_PROCESSING_FAILED";
      // An aggregate overflow in a larger packet is permanent for the same evidence: surface it as the
      // deterministic PACKET_MEDIA_TOO_LARGE (governed human review) instead of retrying a partial packet.
      if (
        code === "PACKET_MEDIA_TOO_LARGE" &&
        messages.length > LEGACY_PACKET_MESSAGES
      ) {
        throw error;
      }
      failureCodes.push(code);
      warnings.push(`${message.providerMessageId}: ${code}`);
      parts.push(
        textPart(
          `${evidenceLabel(message, " media_processing_failed=true")}\n${
            message.content || "[media could not be interpreted]"
          }`,
        ),
      );
    }
  }

  // Never persist an interpretation that silently omits media from a larger packet.
  // Existing small-packet warning behaviour is preserved for compatibility.
  assertOversizedMediaComplete(messages, processedMediaIds, failureCodes);
  return { parts, warnings, processedMediaIds };
}

async function sha256(value: string): Promise<string> {
  const digest = await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(value),
  );
  return [...new Uint8Array(digest)].map((byte) =>
    byte.toString(16).padStart(2, "0")
  ).join("");
}

async function loadPacket(
  admin: SupabaseClient,
  packetId: string,
): Promise<LoadedMessage[]> {
  const [packetResponse, packetTransportErr] = await handleAsync(
    admin
      .from("whatsapp_message_packets")
      .select("id")
      .eq("id", packetId)
      .maybeSingle(),
  );
  if (packetTransportErr) {
    throw new Error(
      `PACKET_LOOKUP_FAILED:${safeString(packetTransportErr.message, 120)}`,
    );
  }
  const { data: packet, error: packetError } = packetResponse;
  if (packetError || !packet) throw new Error("PACKET_NOT_FOUND");

  const [messageResponse, messageTransportErr] = await handleAsync(
    admin
      .from("whatsapp_messages")
      .select(
        "provider_message_id, content, message_type, media_url, message_timestamp, packet_sequence",
      )
      .eq("packet_id", packetId)
      .eq("direction", "inbound")
      .order("packet_sequence", { ascending: true })
      .limit(MAX_PACKET_MESSAGES + 1),
  );
  if (messageTransportErr) {
    throw new Error(
      `PACKET_MESSAGE_LOOKUP_FAILED:${
        safeString(messageTransportErr.message, 120)
      }`,
    );
  }
  const { data, error } = messageResponse;
  if (error) throw new Error("PACKET_MESSAGE_LOOKUP_FAILED");
  const rows = (data ?? []) as PacketMessage[];
  if (!rows.length) throw new Error("PACKET_EMPTY");
  assertPacketMessageCount(rows.length);
  assertProviderIdsPresent(rows);
  return rows.map((row) => ({
    providerMessageId: safeString(row.provider_message_id, 240),
    content: safeString(row.content, 6000),
    messageType: safeString(row.message_type, 40).toLowerCase() || "text",
    mediaUrl: safeString(row.media_url, 5000),
    timestamp: safeString(row.message_timestamp, 80),
  })).filter((row) => Boolean(row.providerMessageId));
}

async function loadCaseContext(
  admin: SupabaseClient,
  caseId: string,
): Promise<LoadedMessage[]> {
  const [rpcResponse, rpcTransportErr] = await handleAsync(
    admin.rpc("whatsapp_case_context_messages", {
      p_case_id: caseId,
    }),
  );
  if (rpcTransportErr) {
    throw new Error(
      `CASE_CONTEXT_MESSAGE_LOOKUP_FAILED:${
        safeString(rpcTransportErr.message, 120)
      }`,
    );
  }
  const { data, error } = rpcResponse;
  if (error) throw new Error("CASE_CONTEXT_MESSAGE_LOOKUP_FAILED");
  const rows = (data ?? []) as PacketMessage[];
  if (!rows.length) throw new Error("CASE_CONTEXT_EMPTY");
  assertPacketMessageCount(rows.length);
  assertProviderIdsPresent(rows);
  return rows.map((row) => ({
    providerMessageId: safeString(row.provider_message_id, 240),
    content: safeString(row.content, 6000),
    messageType: safeString(row.message_type, 40).toLowerCase() || "text",
    mediaUrl: safeString(row.media_url, 5000),
    timestamp: safeString(row.message_timestamp, 80),
  })).filter((row) => Boolean(row.providerMessageId));
}

function parseActiveKnowledgeSnapshotResult(
  data: Record<string, unknown> | null,
  error: { message: string } | null,
): KnowledgeSnapshot {
  if (error) {
    throw new Error(
      `KNOWLEDGE_SNAPSHOT_LOAD_FAILED:${safeString(error.message, 120)}`,
    );
  }
  if (!data || typeof data !== "object") {
    throw new Error("KNOWLEDGE_SNAPSHOT_NOT_ACTIVELY_GOVERNED");
  }
  const id = safeString(data.id, 80);
  const schemaVersion = safeString(data.schema_version, 120);
  const contentChecksum = safeString(data.content_checksum, 80);
  const knowledge = data.knowledge;
  if (
    !id || !schemaVersion || contentChecksum.length !== 64 ||
    !knowledge || typeof knowledge !== "object" || Array.isArray(knowledge)
  ) {
    throw new Error("KNOWLEDGE_SNAPSHOT_MALFORMED");
  }
  return {
    id,
    schema_version: schemaVersion,
    content_checksum: contentChecksum,
    knowledge: knowledge as Record<string, unknown>,
  };
}

async function loadActiveKnowledgeSnapshot(
  admin: SupabaseClient,
): Promise<KnowledgeSnapshot> {
  const [snapshotResponse, snapshotTransportErr] = await handleAsync(
    admin.rpc("whatsapp_active_intelligence_knowledge_snapshot"),
  );
  if (snapshotTransportErr) {
    throw new Error(
      `KNOWLEDGE_SNAPSHOT_LOAD_FAILED:${
        safeString(snapshotTransportErr.message, 120)
      }`,
    );
  }
  return parseActiveKnowledgeSnapshotResult(
    snapshotResponse.data as Record<string, unknown> | null,
    snapshotResponse.error,
  );
}

// skipcq: JS-R1005
export const sanitizeInterpretation = (
  raw: unknown,
  messages: LoadedMessage[],
  infrastructureWarnings: string[],
): Record<string, unknown> => {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
    throw new Error("INTERPRETER_INVALID_SCHEMA");
  }
  const obj = raw as Record<string, unknown>;
  if (
    !obj.conclusion || typeof obj.conclusion !== "object" ||
    Array.isArray(obj.conclusion)
  ) {
    throw new Error("INTERPRETER_INVALID_SCHEMA");
  }

  const conclusionRaw = obj.conclusion as Record<string, unknown>;
  const intent = safeString(conclusionRaw.intent, 32).toUpperCase();
  if (!ALLOWED_INTENTS.has(intent)) {
    throw new Error("INTERPRETER_INVALID_SCHEMA");
  }

  const allowedIds = new Set(
    messages.map((message) => message.providerMessageId),
  );
  const base = sanitizeInterpretResult(
    raw,
    "packet",
    infrastructureWarnings,
    allowedIds,
  );
  if (!base.conclusion.summary || !base.conclusion.recommended_action) {
    throw new Error("INTERPRETER_INVALID_SCHEMA");
  }

  const primaryDepartmentRaw = safeString(conclusionRaw.primary_department, 32)
    .toUpperCase();
  const primaryDepartment = ALLOWED_DEPARTMENTS.has(primaryDepartmentRaw)
    ? primaryDepartmentRaw
    : "";

  const contributorDepartments = safeStringArray(
    conclusionRaw.contributor_departments,
    8,
    32,
  )
    .map((value) => value.toUpperCase())
    .filter((value) => ALLOWED_DEPARTMENTS.has(value));

  const replyClearanceRaw = safeString(conclusionRaw.reply_clearance, 40)
    .toUpperCase();
  const replyClearance = ALLOWED_REPLY_CLEARANCE.has(replyClearanceRaw)
    ? replyClearanceRaw
    : DEFAULT_REPLY_CLEARANCE;

  return {
    ...base,
    conclusion: {
      ...base.conclusion,
      intent,
      primary_department: primaryDepartment,
      contributor_departments: contributorDepartments,
      reply_clearance: replyClearance,
      draft_reply: safeString(conclusionRaw.draft_reply, 4000),
      human_review_required: true,
      automatic_action_authority: "HUMAN_OR_DEPARTMENT_REVIEW_REQUIRED",
    },
  };
};

const str = { type: "STRING" } as const;
const strArray = { type: "ARRAY", items: str } as const;

/**
 * Structured-output contract for the packet interpretation. It mirrors the
 * "Return JSON only" shape in the system prompt; the sanitizer remains the
 * authority and still validates every field fail-closed.
 */
export const PACKET_RESPONSE_SCHEMA: Record<string, unknown> = {
  type: "OBJECT",
  properties: {
    normalized_text: str,
    extracted_text: str,
    language: str,
    confidence: { type: "NUMBER" },
    warnings: strArray,
    source_kind: str,
    conclusion: {
      type: "OBJECT",
      properties: {
        intent: str,
        summary: str,
        explicit_facts: {
          type: "ARRAY",
          items: {
            type: "OBJECT",
            properties: {
              provider_message_id: str,
              kind: str,
              value: str,
            },
            required: ["provider_message_id", "kind", "value"],
          },
        },
        order_lines: {
          type: "ARRAY",
          items: {
            type: "OBJECT",
            properties: {
              product_name: str,
              sku: str,
              quantity: { type: "NUMBER", nullable: true },
              unit: str,
              status: str,
              evidence_ids: strArray,
            },
            required: ["product_name", "status", "evidence_ids"],
          },
        },
        corrections: {
          type: "ARRAY",
          items: {
            type: "OBJECT",
            properties: {
              provider_message_id: str,
              supersedes: str,
              replacement: str,
            },
            required: ["provider_message_id", "replacement"],
          },
        },
        ambiguities: strArray,
        primary_department: str,
        contributor_departments: strArray,
        reply_clearance: str,
        draft_reply: str,
        recommended_action: str,
        human_review_required: { type: "BOOLEAN" },
        automatic_action_authority: str,
      },
      required: ["intent", "summary", "recommended_action"],
    },
  },
  required: ["conclusion"],
};

/** Low-variance decoding: the task is extraction, not generation. */
const PACKET_TEMPERATURE = 0.1;

const DISPATCH_LEASE_MS = 120_000;
const LEASE_SAFETY_MARGIN_MS = 5_000;
/** The longest a provider call can run, reserved for the re-ask. */
const REASK_PROVIDER_BUDGET_MS = GEMINI_TIMEOUT_MS;
/** Compact-output hint appended to the re-ask so it can differ from a truncated first reply. */
const REASK_HINT =
  "Your previous reply was not a complete, valid JSON object for the required schema. Reply again with ONLY the complete JSON object, as compact as possible: short summary, no commentary.";

/** Failures that a single immediate re-ask can plausibly cure (malformed output). */
const RECOVERABLE_OUTPUT_ERRORS = new Set([
  "INTERPRETER_INVALID_JSON",
  "INTERPRETER_INVALID_SCHEMA",
]);

export type AiAttemptDeps = {
  generate: (request: GeminiRequest) => Promise<string>;
  now: () => number;
  /** When the dispatch lease was claimed (request entry); bounds the re-ask. */
  leaseStartedAt: number;
};

/**
 * Bounded recovery: one immediate re-ask when the model returned unusable
 * JSON/schema, only while the lease deadline allows. Anything else, and any
 * second failure, propagates unchanged to the governed retry/dead-letter path.
 */
export async function interpretWithRecovery(
  parts: GeminiPart[],
  messages: LoadedMessage[],
  warnings: string[],
  deps: AiAttemptDeps,
): Promise<Record<string, unknown>> {
  const options = {
    responseSchema: PACKET_RESPONSE_SCHEMA,
    temperature: PACKET_TEMPERATURE,
  };
  for (let attempt = 0;; attempt += 1) {
    try {
      const request = buildGeminiRequest(
        attempt === 0 ? parts : [...parts, textPart(REASK_HINT)],
        options,
      );
      const raw = await deps.generate(request);
      let parsed: unknown;
      try {
        parsed = JSON.parse(raw);
      } catch {
        throw new Error("INTERPRETER_INVALID_JSON");
      }
      return sanitizeInterpretation(parsed, messages, warnings);
    } catch (error) {
      const code = error instanceof Error ? error.message : "";
      // The re-ask may run a full provider call; only start it if that still fits
      // inside the lease measured from the claim, media preparation included.
      const leaseRoom = DISPATCH_LEASE_MS - LEASE_SAFETY_MARGIN_MS -
        REASK_PROVIDER_BUDGET_MS - (deps.now() - deps.leaseStartedAt);
      const canRetry = attempt === 0 && RECOVERABLE_OUTPUT_ERRORS.has(code) &&
        leaseRoom > 0;
      if (!canRetry) throw error;
    }
  }
}

async function callAi(
  apiKey: string,
  messages: LoadedMessage[],
  knowledgeSnapshot: KnowledgeSnapshot,
  leaseStartedAt: number,
) {
  const prepared = await prepareContent(messages, knowledgeSnapshot);
  const interpretation = await interpretWithRecovery(
    prepared.parts,
    messages,
    prepared.warnings,
    {
      generate: (request) => callGeminiGenerateContent(apiKey, request),
      now: Date.now,
      leaseStartedAt,
    },
  );
  return { interpretation, processedMediaIds: prepared.processedMediaIds };
}

