async function retryDispatchLease(
  admin: SupabaseClient,
  lease: DispatchLease,
  error: unknown,
): Promise<void> {
  const code = error instanceof Error
    ? error.message.split(":")[0]
    : "PACKET_AI_FAILED";
  if (code === "DISPATCH_LEASE_SUPERSEDED") return;
  const knowledge = code.startsWith("KNOWLEDGE_SNAPSHOT_");
  try {
    await rpcWithTransport(
      "DISPATCH_RETRY_FAILED",
      admin.rpc("retry_whatsapp_packet_ai_dispatch_job", {
        p_job_id: lease.id,
        p_lease_token: lease.lease_token,
        p_packet_revision: lease.packet_revision,
        p_error_code: code,
        p_error_detail: error instanceof Error
          ? error.message.slice(0, 500)
          : "",
        p_knowledge_authority_failure: knowledge,
      }),
    );
  } catch (retryDispatchError) {
    const message = retryDispatchError instanceof Error
      ? retryDispatchError.message
      : "DISPATCH_RETRY_FAILED";
    throw new Error(message);
  }
}

/**
 * Accepts only a service_role JWT after Supabase verify_jwt has already
 * validated the token signature and project scope at the Edge gateway.
 *
 * Preview runtimes may inject a modern sb_secret_* value into
 * SUPABASE_SERVICE_ROLE_KEY while trusted callers still authenticate with
 * the legacy service_role JWT, so byte-for-byte token/secret equality is
 * intentionally not used here.
 */
export const trustedServiceRoleAuthorization = (
  authorization: string,
): boolean => {
  const match = authorization.trim().match(/^Bearer\s+([^\s]+)$/i);
  if (!match) return false;

  const parts = match[1].split(".");
  if (parts.length !== 3) return false;

  try {
    const encoded = parts[1].replace(/-/g, "+").replace(/_/g, "/");
    const padded = encoded.padEnd(Math.ceil(encoded.length / 4) * 4, "=");
    const decoded = atob(padded);
    const bytes = Uint8Array.from(
      decoded,
      (character) => character.charCodeAt(0),
    );
    const payload = JSON.parse(new TextDecoder().decode(bytes));

    return Boolean(
      payload &&
        typeof payload === "object" &&
        !Array.isArray(payload) &&
        (payload as Record<string, unknown>).role === "service_role",
    );
  } catch {
    return false;
  }
};
async function handleRequest(req: Request): Promise<Response> {
  if (req.method !== "POST") {
    return respond({ success: false, error: "METHOD_NOT_ALLOWED" }, 405);
  }
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
  const authorization = req.headers.get("Authorization") ?? "";
  if (!serviceRoleKey || !trustedServiceRoleAuthorization(authorization)) {
    return respond(
      { success: false, error: "TRUSTED_PROCESSOR_REQUIRED" },
      401,
    );
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL");
  if (!supabaseUrl) {
    return respond({ success: false, error: "WORKER_NOT_CONFIGURED" }, 503);
  }
  const admin = createClient(supabaseUrl, serviceRoleKey, {
    auth: { persistSession: false, autoRefreshToken: false },
  });

  const body = await req.json().catch(() => ({})) as Record<string, unknown>;
  try {
    return respond(await processWorkerRequest(admin, body));
  } catch (error) {
    if (error instanceof WorkerRequestError) {
      return respond(error.body, error.status);
    }
    throw error;
  }
}

/**
 * Trusted in-process worker execution for same-runtime preview certification only.
 * Callers must already hold a service-role Supabase client for the pinned preview project.
 */
export async function processWorkerRequest(
  admin: SupabaseClient,
  body: Record<string, unknown>,
): Promise<Record<string, unknown>> {
  const requestStartedAt = Date.now();
  const claimNext = body.claim_next === true;
  const requestedPacketId = safeString(body.packet_id, 80);
  let lease: DispatchLease | null = null;
  if (claimNext) {
    try {
      lease = await claimDispatchLease(admin);
    } catch (claimError) {
      throw claimError instanceof Error
        ? claimError
        : new Error("DISPATCH_CLAIM_FAILED");
    }
    if (!lease) return { success: true, idle: true };
  } else if (
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
      .test(requestedPacketId)
  ) {
    try {
      lease = await claimDispatchLeaseForPacket(admin, requestedPacketId);
    } catch (claimError) {
      throw claimError instanceof Error
        ? claimError
        : new Error("DISPATCH_CLAIM_FAILED");
    }
    if (!lease) {
      const state = await dispatchJobState(admin, requestedPacketId);
      if (state === "LEASED") {
        return {
          success: true,
          deferred: true,
          reason: "DISPATCH_LEASE_ACTIVE",
          packet_id: requestedPacketId,
        };
      }
      if (state === "COMPLETED") {
        return {
          success: true,
          deferred: true,
          reason: "DISPATCH_ALREADY_COMPLETED",
          packet_id: requestedPacketId,
        };
      }
      throw new WorkerRequestError(
        {
          success: false,
          deferred: true,
          reason: "DISPATCH_LEASE_REQUIRED",
          packet_id: requestedPacketId,
        },
        409,
      );
    }
  } else {
    throw new WorkerRequestError({
      success: false,
      error: "PACKET_ID_REQUIRED",
    }, 400);
  }

  const packetId = lease.packet_id;

  try {
    const continuationInterpretationId =
      await identityConfirmationContinuationInterpretationId(admin, lease);
    if (continuationInterpretationId) {
      const caseResult = await materializeCase(
        admin,
        packetId,
        continuationInterpretationId,
        lease,
      );
      await completeDispatchLease(admin, lease);
      return {
        success: true,
        identityConfirmationContinuation: true,
        packet_id: packetId,
        interpretation_id: continuationInterpretationId,
        communication_case: caseResult,
      };
    }

    const messages = lease?.execution_kind === "CASE_CONTEXT" && lease.case_id
      ? await loadCaseContext(admin, lease.case_id)
      : await loadPacket(admin, packetId);
    const knowledgeSnapshot = await loadActiveKnowledgeSnapshot(admin);
    const providerIds = messages.map((message) => message.providerMessageId);
    const fingerprint = await sha256(
      messages.map((message) =>
        [
          message.providerMessageId,
          message.messageType,
          message.content,
          message.timestamp,
        ].join("|")
      ).join("\n"),
    );

    const { data: existing, error: existingError } = await admin
      .from("whatsapp_packet_ai_interpretations")
      .select("id, interpretation")
      .eq("packet_id", packetId)
      .eq("content_fingerprint", fingerprint)
      .maybeSingle();
    if (existingError) {
      throw new Error(
        `INTERPRETATION_CACHE_LOOKUP_FAILED:${
          safeString(existingError.message, 120)
        }`,
      );
    }

    if (existing?.id) {
      const retried = await prepareContent(messages, knowledgeSnapshot);
      await completeMediaSequentially(
        admin,
        retried.processedMediaIds,
        fingerprint,
      );
      const caseResult = await materializeCase(
        admin,
        packetId,
        String(existing.id),
        lease,
      );
      await applyNonOrderGovernance(
        admin,
        caseResult,
        String(existing.id),
        existing.interpretation,
      );
      await completeDispatchLease(admin, lease);
      return {
        success: true,
        cached: true,
        packet_id: packetId,
        content_fingerprint: fingerprint,
        interpretation: existing.interpretation,
        communication_case: caseResult,
      };
    }

    // MC#629 fix: the key is only needed from this point on (a real AI call).
    // The identity-confirmation-continuation and cached-interpretation paths
    // above never reach here, so they must not depend on this key's presence.
    const apiKey = Deno.env.get("GEMINI_API_KEY");
    if (!apiKey) {
      throw new WorkerRequestError({
        success: false,
        error: "WORKER_NOT_CONFIGURED",
      }, 503);
    }

    const result = await callAi(
      apiKey,
      messages,
      knowledgeSnapshot,
      requestStartedAt,
    );
    await completeMediaSequentially(
      admin,
      result.processedMediaIds,
      fingerprint,
    );

    const interpretationId = await persistInterpretationGoverned(
      admin,
      packetId,
      fingerprint,
      providerIds,
      result.interpretation,
      knowledgeSnapshot,
      lease,
    );

    const caseResult = await materializeCase(
      admin,
      packetId,
      interpretationId,
      lease,
    );
    await applyNonOrderGovernance(
      admin,
      caseResult,
      interpretationId,
      result.interpretation,
    );
    await completeDispatchLease(admin, lease);
    return {
      success: true,
      packet_id: packetId,
      content_fingerprint: fingerprint,
      interpretation: result.interpretation,
      communication_case: caseResult,
    };
  } catch (error) {
    if (lease) {
      await retryDispatchLease(admin, lease, error).catch((retryError) => {
        console.error(
          "[whatsapp-packet-ai-worker]",
          retryError instanceof Error
            ? retryError.message.slice(0, 240)
            : "DISPATCH_RETRY_FAILED",
        );
      });
    }
    throw error;
  }
}

if (import.meta.main) {
  serve(async (req) => {
    try {
      return await handleRequest(req);
    } catch (error) {
      const code = error instanceof Error ? error.message : "PACKET_AI_FAILED";
      console.error("[whatsapp-packet-ai-worker]", code.slice(0, 240));
      return respond({ success: false, error: code.slice(0, 240) }, 502);
    }
  });
}

export { claimDispatchLease, parseDispatchLeaseRow };

/** @file Governed HTTPS media retrieval for WhatsApp B2B interpretation workers. */

export const DEFAULT_WHATSAPP_MEDIA_HOST_SUFFIXES = [
  "click2api.in",
  "lookaside.fbsbx.com",
] as const;

export type GovernedMediaPayload = {
  bytes: Uint8Array;
  mime: string;
};

/** Returns the Supabase project API/storage host derived from injected SUPABASE_URL. */
const supabaseProjectMediaHostSuffixes = (): string[] => {
  const raw = Deno.env.get("SUPABASE_URL") ?? "";
  try {
    const host = new URL(raw).hostname.toLowerCase().replace(/\.$/, "");
    return host ? [host] : [];
  } catch {
    return [];
  }
};

/** Returns configured provider/CDN host suffixes from env plus defaults. */
export const configuredWhatsAppMediaHostSuffixes = (): string[] => {
  const configured = (Deno.env.get("WHATSAPP_MEDIA_ALLOWED_HOSTS") ?? "")
    .split(",")
    .map((host) => host.trim().toLowerCase().replace(/^\.+/, ""))
    .filter(Boolean);
  return [...new Set([
    ...DEFAULT_WHATSAPP_MEDIA_HOST_SUFFIXES,
    ...supabaseProjectMediaHostSuffixes(),
    ...configured,
  ])];
};

/** Parses and validates a WhatsApp provider media URL before any network fetch. skipcq: JS-R1005 */
export const parseGovernedWhatsAppMediaUrl = (mediaUrl: string): URL => {
  let parsed: URL;
  try {
    parsed = new URL(mediaUrl);
  } catch {
    throw new Error("MEDIA_URL_INVALID");
  }
  if (parsed.protocol !== "https:") {
    throw new Error("MEDIA_URL_PROTOCOL_NOT_ALLOWED");
  }
  if (parsed.username || parsed.password) {
    throw new Error("MEDIA_URL_CREDENTIALS_NOT_ALLOWED");
  }
  const hostname = parsed.hostname.toLowerCase().replace(/\.$/, "");
  const allowed = configuredWhatsAppMediaHostSuffixes().some(
    (suffix) => hostname === suffix || hostname.endsWith(`.${suffix}`),
  );
  if (!allowed) throw new Error("MEDIA_HOST_NOT_ALLOWED");
  return parsed;
};

/** Returns true when the host is the verified Click2API provider domain. */
export const isClick2ApiMediaHost = (hostname: string): boolean => {
  const host = hostname.toLowerCase();
  return host === "click2api.in" || host.endsWith(".click2api.in");
};

/** Reads a response body with a hard byte ceiling using bounded streaming. skipcq: JS-R1005 */
export const readBoundedResponseBody = async (
  response: Response,
  maxBytes: number,
): Promise<Uint8Array> => {
  if (!response.body) throw new Error("EMPTY_MEDIA");
  const reader = response.body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;
  let doneReading = false;
  try {
    while (!doneReading) {
      const { done, value } = await reader.read();
      if (done) {
        doneReading = true;
        break;
      }
      if (value === undefined || value.byteLength === 0) continue;
      total += value.byteLength;
      if (total > maxBytes) {
        await reader.cancel("MEDIA_TOO_LARGE").catch(() => undefined);
        throw new Error("MEDIA_TOO_LARGE");
      }
      chunks.push(value);
    }
  } finally {
    reader.releaseLock();
  }
  if (!total) throw new Error("EMPTY_MEDIA");
  const bytes = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return bytes;
};

/** Builds Click2API provider headers when the media host requires them. */
const click2ApiProviderHeaders = (): Record<string, string> => {
  const providerHeaders: Record<string, string> = {};
  const click2ApiKey = Deno.env.get("CLICK2API_API_KEY");
  const accessToken = Deno.env.get("CLICK2API_ACCESS_TOKEN");
  if (click2ApiKey) providerHeaders.apikey = click2ApiKey;
  if (accessToken) providerHeaders.Authorization = `Bearer ${accessToken}`;
  return providerHeaders;
};

/**
 * Internal fetch helper. Caller must pass a URL already validated by
 * parseGovernedWhatsAppMediaUrl (HTTPS, allowlisted host, no credentials).
 */
const fetchValidatedHttpsResponse = async (
  validatedUrl: URL,
  providerHeaders: Record<string, string>,
  timeoutMs: number,
): Promise<Response> => {
  const allowlistedHost = validatedUrl.hostname.toLowerCase();
  const hostAllowed = configuredWhatsAppMediaHostSuffixes().some(
    (suffix) =>
      allowlistedHost === suffix || allowlistedHost.endsWith(`.${suffix}`),
  );
  if (!hostAllowed || validatedUrl.protocol !== "https:") {
    throw new Error("MEDIA_HOST_NOT_ALLOWED");
  }
  // URL validated above (HTTPS + allowlisted host + no credentials in parseGovernedWhatsAppMediaUrl).
  return await fetch(validatedUrl.toString(), {
    headers: providerHeaders,
    redirect: "manual",
    signal: AbortSignal.timeout(timeoutMs),
  });
};

/**
 * Downloads governed WhatsApp media after HTTPS/host/credential validation.
 * Redirects are rejected; only the validated URL is fetched. skipcq: JS-R1005
 */
// skipcq: JS-R1005
export const DEFAULT_MEDIA_FETCH_TIMEOUT_MS = 20_000;

export const downloadGovernedWhatsAppMedia = async (
  mediaUrl: string,
  maxBytes: number,
  timeoutMs: number = DEFAULT_MEDIA_FETCH_TIMEOUT_MS,
): Promise<GovernedMediaPayload> => {
  const parsed = parseGovernedWhatsAppMediaUrl(mediaUrl);
  const providerHeaders = isClick2ApiMediaHost(parsed.hostname)
    ? click2ApiProviderHeaders()
    : {};

  const mediaResponse = await fetchValidatedHttpsResponse(
    parsed,
    providerHeaders,
    Math.max(1, Math.min(timeoutMs, DEFAULT_MEDIA_FETCH_TIMEOUT_MS)),
  );
  if (mediaResponse.status >= 300 && mediaResponse.status < 400) {
    throw new Error("MEDIA_REDIRECT_NOT_ALLOWED");
  }
  if (!mediaResponse.ok) {
    throw new Error(`MEDIA_DOWNLOAD_${mediaResponse.status}`);
  }

  const declaredLength = Number(mediaResponse.headers.get("content-length"));
  if (Number.isFinite(declaredLength) && declaredLength > maxBytes) {
    throw new Error("MEDIA_TOO_LARGE");
  }

  const mime =
    (mediaResponse.headers.get("content-type") || "application/octet-stream")
      .split(";")[0]
      .trim()
      .toLowerCase();
  const bytes = await readBoundedResponseBody(mediaResponse, maxBytes);
  return { bytes, mime };
};

/** @file Strict sanitization for WhatsApp B2B multimodal interpreter JSON output. */

import type { SourceKind } from "./types.ts";

export type ConclusionIntent =
  | "NEW_ORDER"
  | "AMENDMENT"
  | "ENQUIRY"
  | "COMPLAINT"
  | "FINANCE"
  | "OTHER"
  | "UNCLEAR";

export type ExplicitFact = {
  provider_message_id: string;
  kind: string;
  value: string;
};

export type OrderLine = {
  product_name: string;
  sku: string;
  quantity: number | null;
  unit: string;
  status: "explicit" | "interpreted" | "unclear";
  evidence_ids: string[];
};

export type Correction = {
  provider_message_id: string;
  supersedes: string;
  replacement: string;
};

export type AiConclusion = {
  intent: ConclusionIntent;
  summary: string;
  explicit_facts: ExplicitFact[];
  order_lines: OrderLine[];
  corrections: Correction[];
  ambiguities: string[];
  recommended_action: string;
  human_review_required: boolean;
};

export type InterpretResponse = {
  normalized_text: string;
  extracted_text: string;
  language: string;
  confidence: number;
  warnings: string[];
  source_kind: SourceKind;
  conclusion: AiConclusion;
};

const ALLOWED_INTENTS: ConclusionIntent[] = [
  "NEW_ORDER",
  "AMENDMENT",
  "ENQUIRY",
  "COMPLAINT",
  "FINANCE",
  "OTHER",
  "UNCLEAR",
];

/** Returns a bounded trimmed string when the value is textual. */
const safeString = (value: unknown, max: number): string =>
  typeof value === "string" ? value.trim().slice(0, max) : "";

/** Sanitizes an array of bounded strings. */
const sanitizeStringArray = (
  value: unknown,
  maxItems: number,
  maxLength: number,
): string[] => {
  if (!Array.isArray(value)) return [];
  return value
    .filter((entry): entry is string => typeof entry === "string")
    .map((entry) => entry.trim().slice(0, maxLength))
    .filter(Boolean)
    .slice(0, maxItems);
};

/**
 * Splits evidence ids into those present in the governed allowlist and those
 * that are not. Unknown ids are never kept, repaired or replaced: provenance
 * is only ever what the packet actually contains.
 */
const partitionEvidenceIds = (
  ids: string[],
  allowedIds: Set<string>,
): { valid: string[]; rejected: string[] } => ({
  valid: ids.filter((id) => allowedIds.has(id)),
  rejected: ids.filter((id) => !allowedIds.has(id)),
});

/**
 * Bounded record of an item the sanitizer isolated. Free text is reduced to a
 * conservative character set and length so the note can identify the item for a
 * reviewer without carrying arbitrary model or customer text.
 */
const isolationNote = (kind: string, index: number, detail: string): string => {
  const clean = detail.replace(/[^A-Za-z0-9 .,()%/=>-]/g, "").slice(0, 80);
  return `PROVENANCE_ISOLATED:${kind}_${index + 1}:${clean}`;
};

/** Normalizes model intent into the governed intent enum. */
const sanitizeIntent = (value: unknown): ConclusionIntent => {
  const candidate = safeString(value, 32).toUpperCase();
  return ALLOWED_INTENTS.includes(candidate as ConclusionIntent)
    ? candidate as ConclusionIntent
    : "UNCLEAR";
};

// skipcq: JS-R1005
const parseExplicitFact = (
  entry: unknown,
  allowedIds: Set<string>,
  index: number,
  isolated: string[],
): ExplicitFact | null => {
  const obj = entry && typeof entry === "object"
    ? entry as Record<string, unknown>
    : null;
  if (!obj) return null;
  const providerMessageId = safeString(obj.provider_message_id, 240);
  const kind = safeString(obj.kind, 80);
  const factValue = safeString(obj.value, 600);
  if (!providerMessageId || !kind || !factValue) return null;
  if (!allowedIds.has(providerMessageId)) {
    isolated.push(
      isolationNote("explicit_fact", index, `${kind}=${factValue}`),
    );
    return null;
  }
  return { provider_message_id: providerMessageId, kind, value: factValue };
};

/** Sanitizes explicit facts with provenance validation. */
const sanitizeExplicitFacts = (
  value: unknown,
  allowedIds: Set<string>,
  isolated: string[],
): ExplicitFact[] => {
  if (!Array.isArray(value)) return [];
  return value
    .slice(0, 50)
    .map((entry, index) =>
      parseExplicitFact(entry, allowedIds, index, isolated)
    )
    .filter((fact): fact is ExplicitFact => fact !== null);
};

// skipcq: JS-R1005
const parseOrderLine = (
  entry: unknown,
  allowedIds: Set<string>,
  index: number,
  isolated: string[],
): OrderLine | null => {
  const obj = entry && typeof entry === "object"
    ? entry as Record<string, unknown>
    : null;
  if (!obj) return null;
  const productName = safeString(obj.product_name, 240);
  const sku = safeString(obj.sku, 120);
  const quantityRaw = obj.quantity;
  const quantity =
    typeof quantityRaw === "number" && Number.isFinite(quantityRaw) &&
      quantityRaw > 0
      ? quantityRaw
      : null;
  // A quantity with no named product is still evidence ("send 75 boxes"); it is
  // kept as an unresolved line instead of being silently discarded.
  if (!productName && !sku && quantity === null) return null;
  const unit = safeString(obj.unit, 80);
  const rawStatus = safeString(obj.status, 32).toLowerCase();
  let status: OrderLine["status"] =
    rawStatus === "explicit" || rawStatus === "interpreted"
      ? rawStatus
      : "unclear";
  const { valid: evidenceIds, rejected } = partitionEvidenceIds(
    sanitizeStringArray(obj.evidence_ids, 16, 240),
    allowedIds,
  );
  // A line with no product or SKU cannot be identified, so it is never "explicit".
  if (!productName && !sku) status = "unclear";
  // A line whose provenance cannot be proven is kept for the human reviewer
  // but can never stay "explicit"; it is downgraded, never repaired.
  if (
    rejected.length > 0 || (status === "explicit" && evidenceIds.length === 0)
  ) {
    status = "unclear";
    isolated.push(
      isolationNote(
        "order_line",
        index,
        `${productName || sku || "(unnamed)"} qty=${quantity ?? "?"}${
          unit ? ` ${unit}` : ""
        }`,
      ),
    );
  }
  return {
    product_name: productName,
    sku,
    quantity,
    unit,
    status,
    evidence_ids: evidenceIds,
  };
};

/** Sanitizes order lines with provenance validation. */
const sanitizeOrderLines = (
  value: unknown,
  allowedIds: Set<string>,
  isolated: string[],
): OrderLine[] => {
  if (!Array.isArray(value)) return [];
  return value
    .slice(0, 50)
    .map((entry, index) => parseOrderLine(entry, allowedIds, index, isolated))
    .filter((line): line is OrderLine => line !== null);
};

// skipcq: JS-R1005
const parseCorrection = (
  entry: unknown,
  allowedIds: Set<string>,
  index: number,
  isolated: string[],
): Correction | null => {
  const obj = entry && typeof entry === "object"
    ? entry as Record<string, unknown>
    : null;
  if (!obj) return null;
  const providerMessageId = safeString(obj.provider_message_id, 240);
  const supersedes = safeString(obj.supersedes, 500);
  const replacement = safeString(obj.replacement, 500);
  if (!providerMessageId || !replacement) return null;
  if (!allowedIds.has(providerMessageId)) {
    isolated.push(
      isolationNote("correction", index, `${supersedes} -> ${replacement}`),
    );
    return null;
  }
  return { provider_message_id: providerMessageId, supersedes, replacement };
};

/** Sanitizes explicit corrections with provenance validation. */
const sanitizeCorrections = (
  value: unknown,
  allowedIds: Set<string>,
  isolated: string[],
): Correction[] => {
  if (!Array.isArray(value)) return [];
  return value
    .slice(0, 25)
    .map((entry, index) => parseCorrection(entry, allowedIds, index, isolated))
    .filter((correction): correction is Correction => correction !== null);
};

/** Sanitizes the nested conclusion object. */
const sanitizeConclusion = (
  value: unknown,
  allowedIds: Set<string>,
  isolated: string[],
): AiConclusion => {
  const obj = value && typeof value === "object"
    ? value as Record<string, unknown>
    : {};
  const orderLines = sanitizeOrderLines(obj.order_lines, allowedIds, isolated);
  const corrections = sanitizeCorrections(
    obj.corrections,
    allowedIds,
    isolated,
  );
  // If a correction was discarded for unproven provenance, an earlier line may be
  // superseded by something we dropped: no surviving line is trusted as final.
  if (
    isolated.some((note) => note.startsWith("PROVENANCE_ISOLATED:correction_"))
  ) {
    for (const line of orderLines) line.status = "unclear";
  }
  return {
    intent: sanitizeIntent(obj.intent),
    summary: safeString(obj.summary, 2200),
    explicit_facts: sanitizeExplicitFacts(
      obj.explicit_facts,
      allowedIds,
      isolated,
    ),
    order_lines: orderLines,
    corrections,
    ambiguities: sanitizeStringArray(obj.ambiguities, 25, 500),
    recommended_action: safeString(obj.recommended_action, 1800),
    human_review_required: obj.human_review_required !== false,
  };
};

/** Sanitizes interpreter JSON into the governed response contract. skipcq: JS-R1005 */
export const sanitizeInterpretResult = (
  raw: unknown,
  sourceKind: SourceKind,
  infrastructureWarnings: string[],
  allowedIds: Set<string>,
): InterpretResponse => {
  const obj = raw && typeof raw === "object"
    ? raw as Record<string, unknown>
    : {};
  const isolated: string[] = [];
  const conclusion = sanitizeConclusion(obj.conclusion, allowedIds, isolated);
  if (infrastructureWarnings.length > 0 || isolated.length > 0) {
    conclusion.human_review_required = true;
  }
  const confidenceRaw = Number(obj.confidence);
  const confidence = Number.isFinite(confidenceRaw)
    ? Math.max(0, Math.min(1, confidenceRaw))
    : 0;
  return {
    normalized_text: safeString(obj.normalized_text, 12000),
    extracted_text: safeString(obj.extracted_text, 12000),
    language: safeString(obj.language, 120) || "unknown",
    confidence,
    warnings: [
      ...new Set([
        ...isolated,
        ...sanitizeStringArray(obj.warnings, 20, 320),
        ...infrastructureWarnings.map((warning) => warning.slice(0, 320)),
      ]),
    ].slice(0, 24),
    source_kind: sourceKind,
    conclusion,
  };
};

const EXACT_ERROR_STATUS = new Map<string, number>([
  ["INTERPRETER_NOT_CONFIGURED", 503],
  ["INTERPRETER_PROVIDER_RATE_LIMITED", 429],
  ["INTERPRETER_PROVIDER_CREDITS_EXHAUSTED", 503],
  ["INTERPRETER_PROVIDER_AUTH_FAILED", 502],
  ["EMPTY_MEDIA", 422],
  ["AUDIO_TRANSCRIPTION_EMPTY", 422],
  ["MEDIA_TOO_LARGE", 413],
  ["PACKET_MEDIA_TOO_LARGE", 413],
  ["MEDIA_HOST_NOT_ALLOWED", 422],
  ["MEDIA_REDIRECT_NOT_ALLOWED", 422],
]);

const UNSUPPORTED_MIME_CODES = new Set([
  "UNSUPPORTED_IMAGE_TYPE",
  "UNSUPPORTED_AUDIO_TYPE",
  "UNSUPPORTED_VIDEO_TYPE",
  "UNSUPPORTED_DOCUMENT_TYPE",
]);

const MEDIA_URL_PREFIX_CODES = [
  "MEDIA_URL_INVALID",
  "MEDIA_URL_PROTOCOL_NOT_ALLOWED",
  "MEDIA_URL_CREDENTIALS_NOT_ALLOWED",
];

/** Maps interpreter failure codes to HTTP status without widening authority. */
export const statusForInterpretationError = (code: string): number => {
  const exactStatus = EXACT_ERROR_STATUS.get(code);
  if (exactStatus !== undefined) return exactStatus;
  if (UNSUPPORTED_MIME_CODES.has(code)) return 415;
  if (MEDIA_URL_PREFIX_CODES.includes(code) || code.startsWith("MEDIA_URL_")) {
    return 422;
  }
  return 502;
};

/** @file Direct Gemini multimodal provider adapter for governed WhatsApp evidence. */

import { isTransientHttpStatus } from "./integrationRetryContract.ts";

export const GEMINI_MODEL = "gemini-3.6-flash";
export const GEMINI_TIMEOUT_MS = 90_000;
export const GEMINI_MAX_ATTEMPTS = 3;
export const GEMINI_RETRY_DELAYS_MS = [750, 2_000] as const;
export const GEMINI_GENERATE_CONTENT_URL =
  `https://generativelanguage.googleapis.com/v1beta/models/${GEMINI_MODEL}:generateContent`;

export type GeminiPart =
  | { text: string }
  | { inlineData: { mimeType: string; data: string } };

export type GeminiRequest = {
  contents: Array<{ role: "user"; parts: GeminiPart[] }>;
  generationConfig: {
    responseMimeType: "application/json";
    maxOutputTokens: number;
    temperature?: number;
    responseSchema?: Record<string, unknown>;
  };
};

/** Optional structured-output controls; omitted fields keep legacy behaviour. */
export type GeminiRequestOptions = {
  responseSchema?: Record<string, unknown>;
  temperature?: number;
};

type Sleep = (milliseconds: number) => Promise<void>;
type Now = () => number;

/** Encodes bounded governed media bytes for Gemini inlineData. */
function bytesToBase64(bytes: Uint8Array): string {
  let binary = "";
  const chunk = 0x8000;
  for (let offset = 0; offset < bytes.length; offset += chunk) {
    binary += String.fromCharCode(
      ...bytes.subarray(offset, Math.min(offset + chunk, bytes.length)),
    );
  }
  return btoa(binary);
}

/** Builds a Gemini text part without changing evidence text. */
export function textPart(text: string): GeminiPart {
  return { text };
}

/** Builds a Gemini inline media part while preserving the governed MIME type. */
export function inlineMediaPart(
  bytes: Uint8Array,
  mimeType: string,
): GeminiPart {
  return {
    inlineData: {
      mimeType,
      data: bytesToBase64(bytes),
    },
  };
}

/** Builds the bounded JSON-mode Gemini GenerateContent request. */
export function buildGeminiRequest(
  parts: GeminiPart[],
  options: GeminiRequestOptions = {},
): GeminiRequest {
  if (!parts.length) throw new Error("INTERPRETER_REQUEST_EMPTY");
  return {
    contents: [{ role: "user", parts }],
    generationConfig: {
      responseMimeType: "application/json",
      maxOutputTokens: 3600,
      ...(options.temperature === undefined
        ? {}
        : { temperature: options.temperature }),
      ...(options.responseSchema === undefined
        ? {}
        : { responseSchema: options.responseSchema }),
    },
  };
}

/** Removes a single optional Markdown JSON fence without altering JSON content. */
function stripOptionalJsonFence(value: string): string {
  const trimmed = value.trim();
  const fenced = trimmed.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  return fenced ? fenced[1].trim() : trimmed;
}

/** Extracts the first Gemini candidate's textual response and fails closed on malformed/empty payloads. */
export function parseGeminiJsonText(payload: unknown): string {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    throw new Error("INTERPRETER_PROVIDER_MALFORMED");
  }
  const record = payload as Record<string, unknown>;
  const candidates = Array.isArray(record.candidates) ? record.candidates : [];
  const first = candidates[0];
  if (!first || typeof first !== "object" || Array.isArray(first)) {
    throw new Error("INTERPRETER_EMPTY_RESPONSE");
  }
  const content = (first as Record<string, unknown>).content;
  if (!content || typeof content !== "object" || Array.isArray(content)) {
    throw new Error("INTERPRETER_PROVIDER_MALFORMED");
  }
  const parts = Array.isArray((content as Record<string, unknown>).parts)
    ? (content as Record<string, unknown>).parts as unknown[]
    : [];
  const text = parts
    .map((part) => {
      if (!part || typeof part !== "object" || Array.isArray(part)) return "";
      const value = (part as Record<string, unknown>).text;
      return typeof value === "string" ? value : "";
    })
    .join("")
    .trim();
  if (!text) throw new Error("INTERPRETER_EMPTY_RESPONSE");
  const normalized = stripOptionalJsonFence(text);
  if (!normalized) throw new Error("INTERPRETER_EMPTY_RESPONSE");
  return normalized;
}

/** Returns true only for provider failures that are safe to retry without changing authority. */
export function isTransientGeminiStatus(status: number): boolean {
  return isTransientHttpStatus(status);
}

const defaultSleep: Sleep = (milliseconds) =>
  new Promise((resolve) => setTimeout(resolve, milliseconds));

/** Calls Gemini directly with a transferable provider key and bounded transient retries. */
export async function callGeminiGenerateContent(
  apiKey: string,
  request: GeminiRequest,
  fetchImpl: typeof fetch = fetch,
  sleepImpl: Sleep = defaultSleep,
  nowImpl: Now = Date.now,
): Promise<string> {
  if (!apiKey) throw new Error("WORKER_NOT_CONFIGURED");
  const startedAt = nowImpl();
  let lastTransientStatus: number | null = null;

  for (let attempt = 0; attempt < GEMINI_MAX_ATTEMPTS; attempt += 1) {
    const remainingMs = GEMINI_TIMEOUT_MS - (nowImpl() - startedAt);
    if (remainingMs <= 0) {
      if (lastTransientStatus !== null) {
        throw new Error(`INTERPRETER_PROVIDER_${lastTransientStatus}`);
      }
      throw new Error("INTERPRETER_PROVIDER_TIMEOUT");
    }

    let response: Response;
    try {
      response = await fetchImpl(GEMINI_GENERATE_CONTENT_URL, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-goog-api-key": apiKey,
        },
        signal: AbortSignal.timeout(Math.max(1, remainingMs)),
        body: JSON.stringify(request),
      });
    } catch (error) {
      if (error instanceof DOMException && error.name === "TimeoutError") {
        throw new Error("INTERPRETER_PROVIDER_TIMEOUT");
      }
      throw new Error("INTERPRETER_PROVIDER_TRANSPORT");
    }

    if (response.ok) {
      let payload: unknown;
      try {
        payload = await response.json();
      } catch {
        throw new Error("INTERPRETER_PROVIDER_MALFORMED");
      }
      return parseGeminiJsonText(payload);
    }

    const status = response.status;
    if (!isTransientGeminiStatus(status)) {
      throw new Error(`INTERPRETER_PROVIDER_${status}`);
    }
    lastTransientStatus = status;

    if (attempt >= GEMINI_MAX_ATTEMPTS - 1) {
      throw new Error(`INTERPRETER_PROVIDER_${status}`);
    }

    const delayMs = GEMINI_RETRY_DELAYS_MS[attempt] ??
      GEMINI_RETRY_DELAYS_MS[GEMINI_RETRY_DELAYS_MS.length - 1];
    const remainingAfterResponse = GEMINI_TIMEOUT_MS - (nowImpl() - startedAt);
    if (remainingAfterResponse <= delayMs) {
      throw new Error(`INTERPRETER_PROVIDER_${status}`);
    }

    await response.body?.cancel().catch(() => undefined);
    await sleepImpl(delayMs);
  }

  throw new Error(
    lastTransientStatus === null
      ? "INTERPRETER_PROVIDER_TRANSPORT"
      : `INTERPRETER_PROVIDER_${lastTransientStatus}`,
  );
}

/** @file Shared integration retry/error contract for Core Edge boundaries. */

export type IntegrationRetryDisposition = "retryable" | "permanent";

export type BoundedRetryPolicy = {
  maxAttempts: number;
  retryDelaysMs: readonly number[];
  totalBudgetMs?: number;
};

export class IntegrationError extends Error {
  readonly code: string;
  readonly disposition: IntegrationRetryDisposition;

  constructor(
    code: string,
    disposition: IntegrationRetryDisposition,
    message?: string,
  ) {
    super(message ?? code);
    this.name = "IntegrationError";
    this.code = code;
    this.disposition = disposition;
  }
}

/** HTTP statuses safe to retry without changing commercial authority. */
export function isTransientHttpStatus(status: number): boolean {
  return status === 408 || status === 429 || (status >= 500 && status <= 599);
}

/** Classifies an HTTP response status into the canonical integration retry disposition. */
export function classifyHttpStatus(status: number): IntegrationRetryDisposition {
  return isTransientHttpStatus(status) ? "retryable" : "permanent";
}

/** Returns whether an error is explicitly governed as retryable by this contract. */
export function isRetryableIntegrationError(error: unknown): boolean {
  if (error instanceof IntegrationError) {
    return error.disposition === "retryable";
  }
  return false;
}

const defaultSleep = (milliseconds: number): Promise<void> =>
  new Promise((resolve) => setTimeout(resolve, milliseconds));

export type BoundedRetryAttemptContext = {
  signal: AbortSignal;
  deadlineMs?: number;
  remainingBudgetMs?: number;
};

export type ExecuteWithBoundedRetryOptions<T> = {
  policy: BoundedRetryPolicy;
  operation: (
    attempt: number,
    context: BoundedRetryAttemptContext,
  ) => Promise<T>;
  isRetryable?: (error: unknown) => boolean;
  sleep?: (milliseconds: number) => Promise<void>;
  now?: () => number;
};

/** Creates the canonical terminal error emitted when the total retry budget is exhausted. */
const budgetExceeded = (): IntegrationError =>
  new IntegrationError("INTEGRATION_RETRY_BUDGET_EXCEEDED", "permanent");

/** Validates bounded retry policy invariants before any integration operation executes. */
const validatePolicy = (policy: BoundedRetryPolicy): void => {
  if (
    !Number.isFinite(policy.maxAttempts) ||
    !Number.isInteger(policy.maxAttempts) ||
    policy.maxAttempts < 1
  ) {
    throw new IntegrationError("RETRY_POLICY_INVALID", "permanent");
  }
  if (
    policy.totalBudgetMs !== undefined &&
    (!Number.isFinite(policy.totalBudgetMs) || policy.totalBudgetMs <= 0)
  ) {
    throw new IntegrationError("RETRY_POLICY_INVALID", "permanent");
  }
  if (
    policy.retryDelaysMs.some((delay) => !Number.isFinite(delay) || delay < 0)
  ) {
    throw new IntegrationError("RETRY_POLICY_INVALID", "permanent");
  }
};

/**
 * Executes an integration call with bounded attempts, explicit retry classification,
 * and an optional total budget. Permanent failures fail closed immediately.
 *
 * When a total budget is configured, each operation receives an AbortSignal and
 * absolute deadline. The executor races the operation against the remaining
 * budget so a hung operation cannot make the retry loop unbounded.
 */
export async function executeWithBoundedRetry<T>(
  options: ExecuteWithBoundedRetryOptions<T>,
): Promise<T> {
  const {
    policy,
    operation,
    isRetryable = isRetryableIntegrationError,
    sleep = defaultSleep,
    now = Date.now,
  } = options;

  validatePolicy(policy);

  const startedAt = now();
  const deadlineMs = policy.totalBudgetMs === undefined
    ? undefined
    : startedAt + policy.totalBudgetMs;
  let lastRetryableError: unknown = null;

  for (let attempt = 0; attempt < policy.maxAttempts; attempt += 1) {
    const remainingBudgetMs = deadlineMs === undefined
      ? undefined
      : deadlineMs - now();

    if (remainingBudgetMs !== undefined && remainingBudgetMs <= 0) {
      if (lastRetryableError instanceof IntegrationError) {
        throw lastRetryableError;
      }
      throw budgetExceeded();
    }

    const controller = new AbortController();
    const context: BoundedRetryAttemptContext = {
      signal: controller.signal,
      deadlineMs,
      remainingBudgetMs,
    };

    try {
      const operationPromise = operation(attempt, context);
      let value: T;

      if (remainingBudgetMs === undefined) {
        value = await operationPromise;
      } else {
        let timeoutId: ReturnType<typeof setTimeout> | undefined;
        const timeoutPromise = new Promise<never>((_resolve, reject) => {
          timeoutId = setTimeout(() => {
            reject(budgetExceeded());
            controller.abort();
          }, remainingBudgetMs);
        });
        try {
          value = await Promise.race([operationPromise, timeoutPromise]);
        } finally {
          if (timeoutId !== undefined) clearTimeout(timeoutId);
        }

        if (now() >= (deadlineMs as number)) {
          controller.abort();
          throw budgetExceeded();
        }
      }

      return value;
    } catch (error) {
      controller.abort();

      if (!isRetryable(error)) {
        throw error instanceof Error
          ? error
          : new IntegrationError("INTEGRATION_PERMANENT_FAILURE", "permanent");
      }

      lastRetryableError = error;

      if (attempt >= policy.maxAttempts - 1) {
        throw error instanceof Error
          ? error
          : new IntegrationError("INTEGRATION_RETRY_EXHAUSTED", "permanent");
      }

      const delayMs = policy.retryDelaysMs[attempt] ??
        policy.retryDelaysMs[policy.retryDelaysMs.length - 1] ??
        0;

      if (
        deadlineMs !== undefined &&
        now() + delayMs >= deadlineMs
      ) {
        throw error instanceof Error
          ? error
          : budgetExceeded();
      }

      if (delayMs > 0) {
        await sleep(delayMs);
      }
    }
  }

  throw lastRetryableError instanceof Error
    ? lastRetryableError
    : new IntegrationError("INTEGRATION_RETRY_EXHAUSTED", "permanent");
}
